const fld = (n, l, t = 'text', v = '', o) => `<label>${l}${t === 'select' ? `<select name="${n}">${o.map(x => `<option${x === v ? ' selected' : ''}>${esc(x)}</option>`).join('')}</select>` : `<input name="${n}" type="${t}" value="${esc(v)}"${t === 'number' ? ' step="any" inputmode="decimal"' : ''}${t === 'password' ? ' inputmode="numeric" autocomplete="off"' : ''}>`}</label>`;
const form = (id, f, btn = 'Save') => `<form data-f="${id}" class="fg">${f}<button class="btn">${btn}</button></form>`;
const ownForm = (id, f, b) => owner() ? form(id, f, b) : '<p class="mut">View only: the owner records expenses and sales.</p>';
