const kpi = (l, v, s = '', c = '') => `<div class="kpi ${c}"><small>${l}</small><b>${v}</b><em>${s}</em></div>`;
const btn = (a, t, x = '', c = '') => `<button class="btn sm ${c}" data-do="${a}" data-x="${esc(x)}">${t}</button>`;
function toast(m) { document.querySelectorAll('.toast').forEach(x => x.remove()); const t = document.createElement('div'); t.className = 'toast'; t.textContent = m; document.body.appendChild(t); setTimeout(() => t.remove(), m.length > 60 ? 8000 : 2800); }
function chart(series, W = 640, H = 250) {
  const xs = series.flatMap(s => s.p.map(p => p[0])), ys = series.flatMap(s => s.p.map(p => p[1])); if (!xs.length) return '';
  const x1 = Math.max(...xs, 1), y1 = Math.max(...ys, 1) * 1.1, L = 46, sx = x => L + x / x1 * (W - L - 10), sy = y => H - 24 - y / y1 * (H - 34); let g = '';
  for (let i = 0; i <= 4; i++) { const y = y1 * i / 4, x = x1 * i / 4; g += `<line x1="${L}" x2="${W - 10}" y1="${sy(y)}" y2="${sy(y)}" stroke="#d9e4d5"/><text x="${L - 5}" y="${sy(y) + 4}" text-anchor="end" font-size="11" fill="#5b6b61">${n0(y)}</text><text x="${sx(x)}" y="${H - 6}" text-anchor="middle" font-size="11" fill="#5b6b61">${n0(x)}</text>`; }
  const ln = series.map(s => `<polyline fill="none" stroke="${s.c}" stroke-width="3" ${s.d ? 'stroke-dasharray="7 5"' : ''} points="${s.p.map(p => sx(p[0]) + ',' + sy(p[1])).join(' ')}"/>` + (s.d ? '' : s.p.map(p => `<circle cx="${sx(p[0])}" cy="${sy(p[1])}" r="4" fill="${s.c}"/>`).join(''))).join('');
  return `<svg viewBox="0 0 ${W} ${H}" class="chart">${g}${ln}</svg><div class="leg">${series.map(s => `<span><i style="background:${s.c}"></i>${s.n}</span>`).join('')}<span class="mut">x axis: age in days</span></div>`;
}
const go = (v, bid = S.bid, tab = S.tab) => { S.view = v; S.bid = bid; S.tab = tab; render(); window.scrollTo(0, 0); };
