function pcalc() { const r = document.getElementById('pqr'); if (!r) return; const a = +$id('pq1').value, b = +$id('pq2').value, t = +$id('pq3').value; if (!(a > b) || t <= b || t >= a) { r.className = 'al warn'; r.textContent = 'Target must be between the maize and concentrate protein values.'; return; } const c = (t - b) / (a - b) * 100; r.className = 'al ok'; r.innerHTML = `Per 100 kg: <b>${n1(c)} kg concentrate</b> + <b>${n1(100 - c)} kg maize</b> = ${t}% protein. Check energy: add 2-3 kg vegetable oil for broiler feeds, and follow the concentrate label.`; }
