function signIn(u, stay) { S.user = u; u.last = Date.now(); put('users', u); (stay ? localStorage : sessionStorage).setItem(SK, JSON.stringify({ id: u.id, exp: Date.now() + (stay ? 7 * 864e5 : 12 * 36e5) })); actx(); S.view = 'dash'; render(); setTimeout(() => { watch(); checkUpdates(); }, 400); }
